Change `riscv_dispatch_irq()` to:
```c
#define MCAUSE_INTERRUPT  (1ul << 31)

void *riscv_dispatch_irq(uintptr_t mcause, uintreg_t *regs)
{
  if (mcause & MCAUSE_INTERRUPT)
    {
      /* Interrupt */
      uintptr_t cause = mcause & ~MCAUSE_INTERRUPT;
      if (cause == IRQ_M_TIMER)
        {
          up_timer_int();
        }
      else if (cause == IRQ_M_EXT)
